std::vector<Node> nodes;
for (const auto& cell : rt.finite_cells()) {
    // Get cell vertices
    const auto& vertices = cell->vertices();
    for (const auto& vertex : vertices) {
        // Get vertex position
        const auto& point = vertex->point();
        std::array<double, 3> position = {point[0], point[1], point[2]};

        // Get vertex velocity (assuming velocity is stored in vertex properties)
        std::array<double, 3> velocity = {0.0, 0.0, 0.0};
        if (vertex->has_property("velocity")) {
            const auto& vel = vertex->property("velocity");
            velocity = {vel[0], vel[1], vel[2]};
        }

        // Get vertex mass (assuming mass is stored in vertex properties)
        double mass = 1.0; // default mass
        if (vertex->has_property("mass")) {
            mass = vertex->property("mass");
        }

        // Classify node type based on edge length threshold
        NodeType type = NodeType::INTERIOR;
        bool is_boundary = false;
        bool is_near_boundary = false;

        // Check if vertex is on boundary
        for (const auto& edge : vertex->incident_edges()) {
            if (edge->is_constrained()) {
                is_boundary = true;
                break;
            }
        }

        // Check if vertex is near boundary (within threshold distance)
        if (!is_boundary) {
            for (const auto& edge : vertex->incident_edges()) {
                if (edge->length() < threshold) {
                    is_near_boundary = true;
                    break;
                }
            }
        }

        if (is_boundary) {
            type = NodeType::BOUNDARY;
        } else if (is_near_boundary) {
            type = NodeType::NEAR_BOUNDARY;
        }

        // Create and add node
        nodes.push_back(Node{position, velocity, mass, type, time});
    }
}

// Remove duplicate nodes (if any)
std::sort(nodes.begin(), nodes.end(), [](const Node& a, const Node& b) {
    return a.position < b.position;
});
auto last = std::unique(nodes.begin(), nodes.end(), [](const Node& a, const Node& b) {
    return a.position == b.position;
});
nodes.erase(last, nodes.end());

return nodes;
// END_CODE

